import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Adicionar uma borda a uma foto leva só alguns minutos. Você envia a imagem, escolhe um estilo, define o tamanho e a cor e baixa o resultado emoldurado.</p>\n<p>Este passo a passo acompanha o processo inteiro. Ele cobre os estilos sólido, Polaroid e brilho em gradiente, raio dos cantos, sombras e as configurações de exportação que mantêm a moldura com boa aparência.</p>\n<p>No final, você vai conseguir emoldurar uma foto para redes sociais, uma impressão ou um anúncio de produto em qualquer aparelho. Guarde a foto original até conferir o resultado.</p>\n<h2 id=\"before-you-start\">Antes de Começar: Escolha o Visual</h2>\n<p>Decida para que serve a borda antes de abrir a ferramenta. Uma postagem social precisa de uma moldura fina e limpa, enquanto uma impressão precisa de uma borda mais larga estilo passe-partout.</p>\n<p>Pense também na cor. Branco é a escolha mais segura, preto adiciona drama e uma cor combinada com a foto dá uma sensação desenhada.</p>\n<p>Use a foto original, não uma cópia comprimida. Uma borda adicionada a uma original nítida fica limpa, enquanto uma adicionada a uma cópia suave fica áspera nas bordas.</p>\n<p>Abra o <a href=\"/pt/adicionar-borda-a-imagem/\">Gerador de bordas para imagem</a> no seu navegador. Tudo roda localmente, então a sua foto nunca é enviada para um servidor.</p>\n<h2 id=\"step-by-step\">Como Adicionar uma Borda em Seis Passos</h2>\n<p>O processo é o mesmo para cada estilo de borda. Envie, escolha o estilo, defina o tamanho e a cor, confira a prévia e baixe.</p>\n<p>Capriche no tamanho e na cor. Essas duas configurações decidem se a borda emoldura a foto ou a sobrecarrega.</p>\n<ol>\n<li>Envie a sua imagem arrastando para a área de upload, escolhendo no dispositivo ou colando uma captura de tela com Ctrl+V.</li>\n<li>Escolha um estilo de borda: Sólido, Polaroid ou Brilho em gradiente, ou comece por uma das quatro predefinições rápidas de moldura.</li>\n<li>Defina o tamanho da borda entre 1% e 25% e escolha a cor da moldura que combina com a sua foto.</li>\n<li>Ajuste o raio da moldura e o raio da foto para cantos arredondados e adicione uma sombra se quiser profundidade.</li>\n<li>Visualize o resultado, conferindo os cantos e a sombra em fundos claros e escuros.</li>\n<li>Escolha o formato de exportação, PNG ou WebP para manter transparência e sombras, e clique em Baixar.</li>\n</ol>\n<p>Abra o arquivo baixado uma vez antes de compartilhar. Confirme que a borda está uniforme em todos os lados e que a foto dentro continua bonita.</p>\n<h2 id=\"choosing-border-style\">Como Escolher um Estilo de Borda</h2>\n<p>Uma borda sólida é uma única faixa de cor com largura uniforme. É o estilo mais simples e combina com quase qualquer foto, de retratos a fotos de produto.</p>\n<p>Uma borda Polaroid imita filme instantâneo, com uma faixa mais grossa embaixo para uma legenda. Transmite nostalgia e casualidade, o que combina com fotos de férias e memórias.</p>\n<p>Uma moldura com brilho em gradiente mistura cores ao redor da imagem para um visual moderno e digital. Combina com gráficos sociais e cartazes, onde a moldura faz parte do design.</p>\n<p>Comece com sólido se não tiver certeza. É a escolha mais segura, e dá para mudar para um estilo mais elaborado depois de ver como a foto fica emoldurada.</p>\n<h2 id=\"setting-border-size\">Como Definir o Tamanho da Borda</h2>\n<p>O tamanho da borda vai de 1 por cento a 25 por cento da imagem. Uma borda fina de 1 a 3 por cento emoldura a foto sem tirar a atenção dela.</p>\n<p>Uma borda média de 5 a 10 por cento cria uma sensação de galeria. Ela dá espaço para a foto respirar e combina com impressões, portfólios e slides de apresentação.</p>\n<p>Uma borda grande acima de 15 por cento vira uma declaração de design. Combina com cartazes e gráficos sociais, onde a moldura faz parte do visual.</p>\n<p>Lembre-se de que a borda aumenta o tamanho total. Uma foto com uma borda de 10 por cento em cada lado fica 20 por cento mais larga e mais alta que a original.</p>\n<h2 id=\"choosing-colour\">Como Escolher a Cor da Borda</h2>\n<p>Branco é a cor de borda mais segura. Combina com qualquer foto, funciona em qualquer fundo e dá à imagem uma sensação limpa de galeria que nunca parece datada.</p>\n<p>Preto adiciona drama e foco. Combina com fotos de clima pesado, fotos noturnas e arte, onde uma borda clara pareceria deslocada.</p>\n<p>Combine a borda com uma cor da foto para um visual desenhado. Uma borda que pega a cor de um vestido, um céu ou um produto amarra a moldura à imagem.</p>\n<p>Depois de clicar em uma predefinição rápida, você ainda pode mudar a cor da moldura. As predefinições são um ponto de partida, não uma trava, então ajuste a cor para combinar com a sua foto.</p>\n<h2 id=\"setting-corner-radius\">Como Definir o Raio dos Cantos</h2>\n<p>O raio da moldura controla a curvatura da borda externa da borda, enquanto o raio da foto controla a curvatura da borda interna onde a borda encontra a foto.</p>\n<p>Definir os dois com o mesmo valor dá uma moldura arredondada uniforme. O resultado é uma curva limpa e consistente que parece profissional em cartões e postagens sociais.</p>\n<p>Para uma moldura quadrada simples, mantenha os dois raios em zero. Cantos vivos combinam com fotos formais e fotos de produto, onde uma borda arredondada pareceria deslocada.</p>\n<p>Para um estilo Polaroid, mantenha os raios baixos. O visual clássico de filme instantâneo tem cantos quadrados, e arredondá-los demais quebra o clima retrô.</p>\n<h2 id=\"adding-drop-shadow\">Como Adicionar uma Sombra</h2>\n<p>Uma sombra adiciona uma borda escura suave atrás da imagem emoldurada, o que faz parecer que ela flutua sobre a página. Adiciona profundidade e acabamento.</p>\n<p>As sombras funcionam melhor em fundos claros, onde a borda escura é visível. Em um fundo escuro, a sombra se mistura e adiciona pouco à imagem.</p>\n<p>Para manter a sombra, exporte como PNG ou WebP. JPG não tem transparência, então a sombra some em uma exportação JPG e o resultado parece plano.</p>\n<p>Para uma moldura cinza escuro ou pastel sem sombra, desligue a sombra e escolha a cor direto. Uma moldura limpa sem sombra combina com designs minimalistas.</p>\n<h2 id=\"using-quick-presets\">Como Usar as Predefinições Rápidas de Moldura</h2>\n<p>A ferramenta inclui quatro predefinições rápidas de moldura, cada uma definindo estilo, tamanho, cor e sombra em um clique. São um ponto de partida rápido para visuais comuns.</p>\n<p>Clique nas predefinições para ver qual combina com a sua foto. A prévia atualiza na hora, então dá para comparar os visuais em segundos.</p>\n<p>Depois de clicar em uma predefinição, mude qualquer configuração que quiser. Cor, tamanho e sombra são todos ajustáveis, então a predefinição é uma base, não uma resposta final.</p>\n<p>Para um visual consistente em um conjunto de fotos, use a mesma predefinição para todas elas. Um lote de imagens com molduras iguais parece uma série.</p>\n<h2 id=\"polaroid-border\">Como Fazer uma Borda Polaroid</h2>\n<p>Escolha o estilo Polaroid nas opções de borda. A ferramenta aplica o formato clássico automaticamente, incluindo a faixa mais grossa embaixo.</p>\n<p>A faixa inferior dá espaço para uma legenda. Adicione texto ali com a <a href=\"/pt/adicionar-texto-a-imagem/\">ferramenta Adicionar texto a imagem</a> depois de exportar, ou deixe em branco para um visual retrô limpo.</p>\n<p>Mantenha o raio dos cantos baixo para uma moldura Polaroid. O visual clássico de filme instantâneo tem cantos quadrados, e arredondá-los demais quebra o efeito.</p>\n<p>Bordas Polaroid combinam melhor com fotos casuais e pessoais. Elas parecem deslocadas em um retrato formal ou uma foto de produto, onde uma borda sólida limpa é mais adequada.</p>\n<h2 id=\"gradient-glow-frame\">Como Fazer uma Moldura com Brilho em Gradiente</h2>\n<p>Escolha o estilo de brilho em gradiente e defina o ângulo e as cores. O brilho mistura duas ou mais cores ao redor da imagem, criando uma borda suave e brilhante.</p>\n<p>Mudar o ângulo move a mistura ao redor da moldura. As mesmas cores podem produzir muitos visuais diferentes, então experimente alguns ângulos e veja qual combina com a foto.</p>\n<p>Molduras em gradiente funcionam bem em fotos escuras, onde a borda clara adiciona energia. Podem sobrecarregar uma foto clara e arejada, então use quando a imagem precisar de drama.</p>\n<p>Mantenha o brilho sutil para trabalhos profissionais. Um gradiente suave adiciona polimento, enquanto um brilho forte e vivo distrai da própria foto.</p>\n<h2 id=\"preview-and-compare\">Como Visualizar Antes de Baixar</h2>\n<p>Visualize sempre antes de baixar. Confira se a borda está uniforme em todos os lados, se os cantos estão certos e se a cor combina com a foto.</p>\n<p>A prévia mostra um xadrez cinza e branco ao redor da moldura. Esse padrão significa transparência, não um fundo cinza, e mostra onde a imagem é transparente.</p>\n<p>Confira a sombra em um fundo claro se você adicionou uma. Uma sombra invisível em uma prévia escura pode ser clara na página branca onde a imagem vai viver.</p>\n<p>Se a borda parecer grossa ou fina demais, ajuste o tamanho e confira de novo. Uma pequena mudança em porcentagem pode fazer uma grande diferença na sensação da moldura.</p>\n<h2 id=\"choosing-export-format\">Como Escolher o Formato de Exportação</h2>\n<p>Escolha PNG quando a moldura tiver cantos arredondados ou uma sombra. PNG preserva transparência, então os cantos continuam transparentes e a sombra sobrevive.</p>\n<p>Escolha WebP quando quiser arquivos pequenos com transparência. Funciona bem para imagens da web, embora alguns sistemas mais antigos ainda rejeitem o formato.</p>\n<p>Escolha JPG só para uma borda sólida retangular sem sombra. JPG achata tudo em um fundo sólido, o que é bom para uma moldura simples.</p>\n<p>Lembre-se de que o controle de qualidade some para PNG, porque PNG não tem perda e não tem configuração de qualidade para ajustar. Isso é comportamento normal, não um problema da ferramenta.</p>\n<h2 id=\"adding-border-on-mobile\">Como Adicionar uma Borda no Celular ou Tablet</h2>\n<p>A ferramenta funciona em telas de toque, então dá para emoldurar uma foto no próprio celular que a tirou. Envie da galeria, escolha uma predefinição e baixe o resultado.</p>\n<p>As predefinições rápidas são o caminho mais fácil em uma tela pequena. Um toque define estilo, tamanho, cor e sombra, e dá para ajustar a partir daí se precisar.</p>\n<p>Confira a prévia em tamanho real antes de baixar. Uma borda que parece boa em uma tela pequena de celular pode ser grossa ou fina demais quando vista no computador.</p>\n<p>Os arquivos baixados vão para a sua pasta de downloads. De lá, você pode compartilhar a foto emoldurada direto no WhatsApp, por e-mail ou em uma postagem.</p>\n<h2 id=\"troubleshooting\">Solução de Problemas Comuns com Bordas</h2>\n<p>Se a sombra sumiu, confira o formato de exportação. JPG não tem transparência, então a sombra só sobrevive em exportações PNG ou WebP.</p>\n<p>Se os cantos parecerem quadrados quando você queria redondos, confira o raio da moldura e o raio da foto. Os dois precisam ser definidos para uma moldura arredondada uniforme.</p>\n<p>Se a borda parecer irregular, confira a configuração de tamanho. Uma borda definida como porcentagem pode parecer diferente em fotos altas e largas, então ajuste para o formato.</p>\n<p>Se a imagem emoldurada estiver grande demais para o destino, reduza o tamanho da borda ou redimensione a foto primeiro. Uma borda aumenta as dimensões totais, então uma moldura larga pode empurrar o arquivo para além de um limite de tamanho.</p>\n<h2 id=\"framing-screenshots\">Como Emoldurar uma Captura de Tela</h2>\n<p>Cole uma captura de tela direto com Ctrl+V para pular o passo de salvar. A imagem aparece na ferramenta na hora, pronta para emoldurar.</p>\n<p>Uma borda branca fina com uma sombra suave faz uma captura de tela parecer um cartão. Ela separa a captura da página e a deixa com aparência polida.</p>\n<p>Mantenha a borda fina para capturas de tela. Uma moldura grossa ocupa espaço que o conteúdo da captura precisa, principalmente quando o texto na captura é pequeno.</p>\n<p>Exporte capturas emolduradas como PNG. O formato sem perda mantém o texto pequeno nítido, o que importa quando a captura deve mostrar uma configuração ou uma mensagem de erro.</p>\n<h2 id=\"quick-tips\">Dicas Rápidas para Bordas Melhores</h2>\n<p>Comece com uma predefinição e ajuste a partir daí. As molduras rápidas dão uma boa base em um clique, e o ajuste fino leva só alguns segundos.</p>\n<p>Mantenha a borda fina para redes sociais. Uma moldura grossa ocupa espaço em uma prévia pequena de feed, deixando menos espaço para a própria foto.</p>\n<p>Use o mesmo estilo de borda em um conjunto de fotos. A consistência faz uma série parecer profissional, enquanto molduras misturadas parecem aleatórias.</p>\n<p>Salve a foto original sem borda. Depois que uma borda é achatada em uma exportação, ela não pode ser removida daquele arquivo, então a original é a sua única cópia limpa.</p>\n<h2 id=\"border-for-presentation\">Como Adicionar uma Borda a uma Imagem de Slide de Apresentação</h2>\n<p>Uma foto usada em um slide costuma precisar de uma borda para separá-la do fundo do slide. Uma moldura branca fina com uma sombra suave faz a imagem parecer um cartão no slide.</p>\n<p>Mantenha a borda fina para slides. Uma moldura grossa ocupa espaço que a foto e o texto precisam, principalmente quando o slide já tem título e tópicos.</p>\n<p>Combine a cor da borda com o tema do slide. Uma borda branca combina com um tema claro, enquanto uma borda escura combina com um tema escuro, e uma moldura fora do tema parece acidental.</p>\n<p>Exporte a imagem do slide emoldurada como JPG com qualidade alta. O slide vai ser projetado grande, então a foto e a borda precisam continuar nítidas.</p>\n<p>Para ideias de estilo, leia <a href=\"/pt/blog/moldura-para-foto-estilos/\">Moldura para foto: estilos para Instagram, impressão e produto</a>. Para a visão geral completa, veja <a href=\"/pt/blog/como-colocar-borda-em-foto-guia/\">Como colocar borda em foto: guia completo</a>, e para arredondar os cantos de uma foto emoldurada, experimente a <a href=\"/pt/arredondar-cantos-da-imagem/\">ferramenta Arredondar cantos da imagem</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Como adiciono uma borda branca ao redor de uma foto?","answer":"Envie a foto, escolha o estilo Sólido, defina a cor como branco e escolha um tamanho de 1 a 3 por cento para uma moldura fina ou de 5 a 10 por cento para uma sensação de galeria. Visualize o resultado e exporte como JPG para uma moldura retangular simples, ou PNG se adicionar cantos arredondados ou uma sombra."},{"question":"Dá para adicionar uma borda a uma captura de tela no celular?","answer":"Sim. Abra o gerador de bordas no navegador do celular, envie a captura da galeria e toque em uma predefinição rápida para uma moldura instantânea. Uma borda branca fina com uma sombra suave faz a captura parecer um cartão. Exporte como PNG para manter o texto nítido."},{"question":"Por que a prévia mostra um xadrez cinza ao redor da minha moldura?","answer":"O xadrez significa transparência, não um fundo cinza. Ele mostra onde a imagem é transparente, como ao redor de cantos arredondados ou atrás de uma sombra. Exporte como PNG ou WebP para manter essa transparência no arquivo final."},{"question":"Que tamanho de borda devo usar para uma postagem no Instagram?","answer":"Uma borda fina de 1 a 3 por cento funciona melhor, já que uma moldura grossa ocupa espaço em uma prévia pequena de feed. Mantenha o estilo consistente nas suas postagens para o seu feed ter um visual reconhecível. Branco é a cor mais segura."},{"question":"Dá para mudar a cor depois de clicar em uma predefinição rápida?","answer":"Sim. As predefinições definem estilo, tamanho, cor e sombra como ponto de partida, e cada configuração continua ajustável depois. Clique em uma predefinição e mude a cor da moldura ou qualquer outra configuração para combinar com a sua foto."},{"question":"Adicionar uma borda corta alguma parte da minha foto?","answer":"Não. Uma borda adiciona pixels ao redor da foto em vez de remover, então nada na imagem é cortado. A imagem final é maior que a original pela largura da borda em cada lado."}];
